161	    public String getLocality() {
162	        return CityRegion.of(this.city);
163	    }
164	
165	    /**
166	     * The owner's membership tier, derived from its state: {@code GOLD} when the owner's household
167	     * had 3 or more members at creation ({@link #getHouseholdSize()} is 3 or more); otherwise
168	     * {@code SILVER} when the owner had no namesakes at creation ({@link #getNamesakeCount()} is 0)
169	     * and has an email address, otherwise {@code BRONZE}.
170	     */
171	    public String getMembershipTier() {
172	        if (this.householdSize != null && this.householdSize >= 3) {
173	            return "GOLD";
174	        }
175	        boolean unique = Integer.valueOf(0).equals(this.namesakeCount);
176	        return unique && StringUtils.hasText(this.email) ? "SILVER" : "BRONZE";
177	    }
