179	    protected Set<Pet> getPetsInternal() {
180	        if (this.pets == null) {
181	            this.pets = new HashSet<>();
182	        }
183	        return this.pets;
184	    }
185	
186	    protected void setPetsInternal(Set<Pet> pets) {
187	        this.pets = pets;
188	    }
189	
190	    public List<Pet> getPets() {
191	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
192	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
193	        return Collections.unmodifiableList(sortedPets);
194	    }
195	
196	    public void setPets(List<Pet> pets) {
197	        this.pets = new HashSet<>(pets);
198	    }
199	
200	    public void addPet(Pet pet) {
201	        getPetsInternal().add(pet);
202	        pet.setOwner(this);
203	    }
204	
205	    /**
206	     * Return the Pet with the given name, or null if none found for this Owner.
207	     *
208	     * @param name to test
209	     * @return true if pet name is already in use
210	     */
211	    public Pet getPet(String name) {
212	        return getPet(name, false);
213	    }
214	
215	    /**
216	     * Return the Pet with the given name, or null if none found for this Owner.
217	     *
218	     * @param name to test
219	     * @return true if pet name is already in use
220	     */
221	    public Pet getPet(String name, boolean ignoreNew) {
222	        name = name.toLowerCase();
223	        for (Pet pet : getPetsInternal()) {
224	            if (!ignoreNew || !pet.isNew()) {
225	                String compName = pet.getName();
226	                compName = compName.toLowerCase();
227	                if (compName.equals(name)) {
228	                    return pet;
229	                }
230	            }
231	        }
232	        return null;
233	    }
234	
235	    public Pet getPet(Integer petId) {
236	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
237	    }
238	
239	    @Override
240	    public String toString() {
241	        return new ToStringCreator(this)
242	
243	            .append("id", this.getId())
244	            .append("new", this.isNew())
245	            .append("lastName", this.getLastName())
246	            .append("firstName", this.getFirstName())
247	            .append("address", this.address)
248	            .append("city", this.city)
249	            .append("telephone", this.telephone)
250	            .toString();
251	    }
252	}
