4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Emits an audit trail line for a successfully created owner via the dedicated
10	 * {@code AUDIT} logger, recording the owner id, its {@code customerCode} and its
11	 * {@code registrationDate}. Runs after {@link SaveOwner} so the id is assigned.
12	 */
13	public class AuditOwnerCreated {
14	
15	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
16	
17	    public void service(@Val Owner owner) {
18	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
19	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
20	    }
21	}
