        if (this.householdSize != null && this.householdSize >= 3) {
            return "GOLD";
        }
        boolean unique = Integer.valueOf(0).equals(this.namesakeCount);
        return unique && StringUtils.hasText(this.email) ? "SILVER" : "BRONZE";
